import fs from 'node:fs/promises';
import { format } from 'prettier';

const documents = {};
for (const name of ['signatures', 'package', 'unified']) {
  documents[name] = JSON.parse(
    await fs.readFile(new URL(name + '.schema.json', import.meta.url), 'utf8'),
  );
}
const target = new URL(
  '../../clients/dsh-plugin/src/generated/resource-schema-data.js',
  import.meta.url,
);
const output = await format(
  '// Generated by contracts/resource/generate-runtime-schemas.mjs; do not edit.\nexport default ' +
    JSON.stringify(documents) +
    ';\n',
  { parser: 'babel', singleQuote: true },
);
if (process.argv.includes('--check')) {
  if ((await fs.readFile(target, 'utf8')).replaceAll('\r\n', '\n') !== output)
    throw new Error('Resource runtime schemas need regeneration');
} else {
  await fs.writeFile(target, output);
}
